-- Bloco 9: pedidos de DEMONSTRAÇÃO dos últimos 30 dias, para o dashboard ter o que mostrar (faturamento por dia,
-- top 5 pratos, ticket médio). Todos ficam FINALIZADO, do cliente "Cliente Demonstração", e nenhum é de hoje:
-- os números de HOJE no dashboard vêm só dos pedidos reais. O estoque não é alterado (considere que o estoque
-- inicial da V6 já foi contado depois dessas vendas). As datas usam o horário de Brasília (UTC-3).


-- Se algum prato tiver sido renomeado e o pedido ficou sem itens, ele não entra
DELETE FROM pedido WHERE observacoes LIKE 'DEMO-%' AND id NOT IN (SELECT pedido_id FROM pedido_item);
-- Total de cada pedido = soma dos itens (preço do prato no cardápio)
UPDATE pedido p SET valor_total = (SELECT SUM(i.quantidade * i.preco_unitario) FROM pedido_item i WHERE i.pedido_id = p.id)
WHERE p.observacoes LIKE 'DEMO-%';
-- Linha do tempo: recebido pelo cliente e finalizado pela gerência 50 minutos depois
  SELECT id, 'RECEBIDO', cliente_id, created_at FROM pedido WHERE observacoes LIKE 'DEMO-%';
  SELECT p.id, 'FINALIZADO', (SELECT u.id FROM usuario u WHERE u.email = 'gerente@email.com'), p.updated_at FROM pedido p WHERE p.observacoes LIKE 'DEMO-%';
UPDATE pedido SET observacoes = NULL WHERE observacoes LIKE 'DEMO-%';
